import{_ as t,c as o,o as n,a2 as r}from"./chunks/framework.CFHYvIe4.js";const g=JSON.parse('{"title":"Contributing to S1API","description":"","frontmatter":{},"headers":[],"relativePath":"contributing/index.md","filePath":"contributing/index.md","lastUpdated":1756461828000}'),i={name:"contributing/index.md"};function a(s,e,d,l,u,c){return n(),o("div",null,e[0]||(e[0]=[r('<h1 id="contributing-to-s1api" tabindex="-1">Contributing to S1API <a class="header-anchor" href="#contributing-to-s1api" aria-label="Permalink to &quot;Contributing to S1API&quot;">​</a></h1><p>Welcome, potential contributor! We appreciate your interest in the S1API project. This guide will help you get started with contributing to the project.</p><h2 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting Started&quot;">​</a></h2><p>S1API is an open source collaboration project aimed at standardizing Schedule One modding processes. The goal is to provide a standard place for common functionalities so modders can focus on making content versus reverse engineering the game.</p><h2 id="how-to-build-the-project" tabindex="-1">How to Build the Project <a class="header-anchor" href="#how-to-build-the-project" aria-label="Permalink to &quot;How to Build the Project&quot;">​</a></h2><p>Before contributing, you&#39;ll need to set up your development environment and learn how to build the project. Please refer to our detailed <a href="/S1API-docs/contributing/building.html">Building the Project</a> guide.</p><h2 id="proper-contributing-channels" tabindex="-1">Proper Contributing Channels <a class="header-anchor" href="#proper-contributing-channels" aria-label="Permalink to &quot;Proper Contributing Channels&quot;">​</a></h2><ul><li><strong>GitHub Issues</strong>: For bug reports, feature requests, and general discussion</li><li><strong>Pull Requests</strong>: For submitting your contributions</li><li><strong>Discord Server</strong>: For real-time discussion and collaboration (link to be added)</li></ul><h2 id="contribution-process" tabindex="-1">Contribution Process <a class="header-anchor" href="#contribution-process" aria-label="Permalink to &quot;Contribution Process&quot;">​</a></h2><ol><li><p><strong>Fork the Repository</strong>: Start by forking the S1API repository to your GitHub account.</p></li><li><p><strong>Set Up Development Environment</strong>: Clone your fork to your local machine and set up the development environment.</p></li><li><p><strong>Choose an Issue</strong>: Look for open issues on the GitHub issue tracker, or propose a new feature or improvement.</p></li><li><p><strong>Create a Branch</strong>: Create a new branch for your work with a descriptive name.</p></li><li><p><strong>Implement Changes</strong>: Make your changes following our <a href="/S1API-docs/contributing/coding-standards.html">Coding Standards</a>.</p></li><li><p><strong>Write Tests</strong>: Add appropriate tests for your changes.</p></li><li><p><strong>Submit a Pull Request</strong>: Push your changes to your fork and submit a pull request to the main repository.</p></li><li><p><strong>Code Review</strong>: Your code will be reviewed by maintainers, who may request changes.</p></li><li><p><strong>Merge</strong>: Once approved, your changes will be merged into the main codebase.</p></li></ol><h2 id="understanding-the-coding-standards" tabindex="-1">Understanding the Coding Standards <a class="header-anchor" href="#understanding-the-coding-standards" aria-label="Permalink to &quot;Understanding the Coding Standards&quot;">​</a></h2><p>Before contributing, please thoroughly read over our <a href="/S1API-docs/contributing/coding-standards.html">Coding Standards</a> documentation. These standards ensure the project remains consistent and predictable.</p><h2 id="documentation-guidelines" tabindex="-1">Documentation Guidelines <a class="header-anchor" href="#documentation-guidelines" aria-label="Permalink to &quot;Documentation Guidelines&quot;">​</a></h2><p>We use VitePress for our documentation site. If you&#39;re contributing to the documentation, please refer to our <a href="/S1API-docs/contributing/vitepress-guide.html">VitePress Documentation Guide</a> to understand how to write and format content effectively.</p>',14)]))}const p=t(i,[["render",a]]);export{g as __pageData,p as default};
